DC = ['key:Escape', 'user:manager', 'click:menutop:Accounts & Reports', 'click:menuleaf:Day closing']
chapter(19, 'Day close', 'Walk the seven steps of the Day closing page: preflight, room nights, the cash shift, closing, the summary, the next day and corrections. The demo day cannot close because ten stays are due out.',
        'Meera (Manager)', 'manager', menu='Accounts & Reports > Day closing')
step('It is 26 October. Meera, the Manager, is on Modules Home. At the end of every day she closes the business date.', 'Closing the day freezes the figures of the day, posts the room nights and opens the next date.', target='sel:.fit-home-grid', auto=['key:Escape', 'user:manager'], action='read', expect='Modules Home for Meera.', check="ctx.uid==='manager'")
tile('Accounts & Reports', 'Click the Accounts & Reports tile.', 'Day closing, reports, accounting, compliance and the assistant are here.', expect='The Accounts & Reports page opens.')
leaf('Accounts & Reports', 'Day closing', 'Click the Day closing tile.', 'The page leads you through the close in order.', expect='The Day closing page opens.', check="ctx.page==='closing'")
read('The page shows the current business date, 26 Oct 2026, and seven steps: 1 Preflight, 2 Post room nights, 3 Cash shift, 4 Close business date, 5 Closing summary, 6 Open next business day, 7 Reopen & corrections. Each shows its state: done, current step, waiting or blocked.', 'The order cannot be skipped, so the close is always complete.', target='btn:1. Preflight', expect='The seven closing steps.')
click('btn:1. Preflight', 'Click 1. Preflight.', 'The preflight lists everything that must be settled before the day can close.', expect='The preflight checks are listed.')
read('Arrivals, expired holds, approvals, expenses and restaurant checks are all clear. One check is blocked: Overdue departures resolved, ten guests are due out today, from Ananya Rao in room 101 to Aditi Nair in room 207. Each must be settled and checked out, or the stay extended.', 'A guest who should have left must be dealt with, so the room is not sold twice.', target='text:Overdue departures', expect='The blocked check lists ten guests.')
click('btn:2. Post room nights', 'Click 2. Post room nights.', 'The night audit posts one room charge for every in-house stay; it is safe to run twice.', expect='The step shows that room nights are posted.')
click('btn:Preview report', 'Click Preview report.', 'The preview shows the closing report as it would be, without closing the day.', expect='The closing preview opens.')
step('Close the preview. Priya counts the drawer on the Cashier shift page. The expected cash is Rs 9,625; she types the counted amount.', 'The shift must be counted and closed before the day can close; a difference needs a reason.', target='btn:Submit count & close shift',
     auto=['key:Escape', 'user:cashier', 'click:menutop:Cash & Billing', 'click:menuleaf:Cashier shift', 'click:btn:2. Count & result', 'typedrawer:field:Physical cash counted'], action='type', expect='The Difference box shows zero.', check="has('Submit count')")
read('With the count equal to the expected cash the Difference box shows zero, and Submit count & close shift would close the shift. A difference needs a reason and the approval of another user. The training does not submit here, because the Cashier shift page and the close command disagree on the expected cash in this demo (see TRAINING_NOTES).', 'The shift must be closed before the day can close.', target='btn:Submit count & close shift', expect='The count form with a zero difference.')
step('Meera opens Day closing again. Step 3, Cash shift, still waits for the close of the shift; step 4 is blocked by the ten overdue departures.', 'Close business date stays grey until every check is green.', target='btn:4. Close business date', auto=DC, action='click', expect='Day closing shows step 4 blocked.', check="ctx.page==='closing'")
click('btn:4. Close business date', 'Click 4. Close business date.', 'The Close button names the date, Close 26 Oct, and is available only when nothing blocks it.', expect='The reasons that block the close are listed.')
click('btn:5. Closing summary', 'Click 5. Closing summary.', 'After the close, the summary shows net receipts, cash, tax and the room figures of the day.', expect='The closing summary preview is shown.')
click('btn:6. Open next business day', 'Click 6. Open next business day.', 'After the close, Open next business day moves the date to 27 Oct and carries the cash forward; each cashier opens a new shift.', expect='The step shows the next date, 27 Oct, waiting for the close.')
click('btn:7. Reopen', 'Click 7. Reopen & corrections.', 'If an error is found after the close, the Owner can reopen the day with a reason; HCC records every reopening and closes the day again.', expect='The reopening step shows nothing reopened.')
read('To finish the training day, each of the ten guests would be checked out as in chapter 8 and the day closed with the Close 26 Oct button. The demo does not do this, so the data of the next chapters stays on 26 October.', 'The close is the last job of every day; the owner reads its result in the digest next morning.', target='btn:Close 26 Oct', expect='The disabled Close 26 Oct button.')
